package com.mygo.music;
import android.content.Context;
import android.graphics.*;
import android.os.SystemClock;
import android.view.View;
import android.view.ViewConfiguration;

/** Own bounded album copy; each scene has its own geometry. Sound-driven marks use measured data only. */
final class ThemeArtworkView extends View {
 private final Paint paint=new Paint(3);private final Matrix matrix=new Matrix();private Bitmap bitmap;private BitmapShader shader;
 private String theme="dynamic",name="",artist="";private boolean playing,active=true,quiet,light;private float phase,progress,gain=1;private long frame;private int accent=0xffa0ddd8,style,frameIntervalMs;
 ThemeArtworkView(Context c){super(c);setLayerType(LAYER_TYPE_SOFTWARE,null);}
 void theme(String id,int color,boolean light,int style,float gain){this.theme=id;accent=color;this.light=light;this.style=style;this.gain=gain;invalidate();}
 @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);setLayerType((long)w*h*4>ViewConfiguration.get(getContext()).getScaledMaximumDrawingCacheSize()?LAYER_TYPE_NONE:LAYER_TYPE_SOFTWARE,null);}
 void frameInterval(int millis){frameIntervalMs=Math.max(0,Math.min(1000,millis));}
 void art(Bitmap source){free();if(source!=null&&!source.isRecycled()){float f=Math.min(1,640f/Math.max(source.getWidth(),source.getHeight()));Bitmap b=Bitmap.createScaledBitmap(source,Math.max(1,Math.round(source.getWidth()*f)),Math.max(1,Math.round(source.getHeight()*f)),true);bitmap=b==source?source.copy(Bitmap.Config.ARGB_8888,false):b;shader=new BitmapShader(bitmap,Shader.TileMode.CLAMP,Shader.TileMode.CLAMP);}invalidate();}
 void state(String n,String a,int position,int duration,boolean p,boolean visible,boolean reduce){advance();name=n;artist=a;progress=duration>0?Math.max(0,Math.min(1,position/(float)duration)):0;playing=p;active=visible;quiet=reduce;invalidate();}
 private void advance(){long now=SystemClock.uptimeMillis();if(frame>0&&playing&&active&&!quiet)phase=(phase+Math.min(80,now-frame)*.012f)%360;frame=now;}
 void active(boolean value){advance();active=value;if(value)invalidate();}
 float phase(){advance();return phase;}
 private void cover(Canvas c,RectF r,float radius){paint.setColor(light?0xffcfdedb:0xff31515d);if(shader!=null){float s=Math.max(r.width()/bitmap.getWidth(),r.height()/bitmap.getHeight());matrix.setScale(s,s);matrix.postTranslate(r.centerX()-bitmap.getWidth()*s/2,r.centerY()-bitmap.getHeight()*s/2);shader.setLocalMatrix(matrix);paint.setShader(shader);}c.drawRoundRect(r,radius,radius,paint);paint.setShader(null);}
 private String fit(String s,float width){while(s.length()>1&&paint.measureText(s)>width)s=s.substring(0,s.length()-1);return s;}
 @Override protected void onDraw(Canvas c){advance();float w=getWidth(),h=getHeight(),s=Math.min(w,h),cx=w/2,cy=h/2;paint.setShader(null);paint.setAlpha(255);paint.setStyle(Paint.Style.FILL);paint.clearShadowLayer();
  if(theme.equals("cassette")){float width=Math.min(w*.95f,h*1.62f),height=width*.63f,x=(w-width)/2,y=(h-height)/2;paint.setColor(0xff27353c);paint.setShadowLayer(s*.04f,0,s*.02f,0x99000000);c.drawRoundRect(x,y,x+width,y+height,width*.05f,width*.05f,paint);paint.clearShadowLayer();paint.setColor(0xffded4b9);c.drawRoundRect(x+width*.04f,y+height*.06f,x+width*.96f,y+height*.68f,width*.025f,width*.025f,paint);paint.setColor(accent);c.drawRect(x+width*.04f,y+height*.13f,x+width*.96f,y+height*.28f,paint);paint.setColor(0xff20323a);c.drawRoundRect(x+width*.12f,y+height*.34f,x+width*.88f,y+height*.60f,width*.02f,width*.02f,paint);
   for(int i=0;i<2;i++){float x0=x+width*(i==0?.28f:.72f),y0=y+height*.47f,r=width*(.073f+.041f*(i==0?1-progress:progress));paint.setColor(0xff72614d);c.drawCircle(x0,y0,r*1.2f,paint);paint.setColor(0xffd6d6cb);c.drawCircle(x0,y0,width*.065f,paint);c.save();c.rotate(phase*(i==0?2:2.2f),x0,y0);paint.setColor(0xff34444b);for(int k=0;k<6;k++){c.save();c.rotate(k*60,x0,y0);c.drawRect(x0-width*.012f,y0-width*.05f,x0+width*.012f,y0-width*.025f,paint);c.restore();}c.restore();paint.setColor(0xff27393d);c.drawCircle(x0,y0,width*.018f,paint);}paint.setTextAlign(Paint.Align.CENTER);paint.setColor(0xff20313a);paint.setTextSize(width*.043f);c.drawText(fit(name,width*.82f),cx,y+height*.24f,paint);paint.setColor(0xff81918e);Path lower=new Path();lower.moveTo(x+width*.18f,y+height*.96f);lower.lineTo(x+width*.27f,y+height*.73f);lower.lineTo(x+width*.73f,y+height*.73f);lower.lineTo(x+width*.82f,y+height*.96f);lower.close();c.drawPath(lower,paint);paint.setColor(0xff23353a);for(float k:new float[]{.29f,.71f})c.drawCircle(x+width*k,y+height*.86f,width*.025f,paint);paint.setTextSize(width*.028f);paint.setColor(0xffd5e3db);c.drawText("A · MYGO MUSIC",cx,y+height*.71f,paint);paint.setTextAlign(Paint.Align.LEFT);
  }else if(theme.equals("polaroid")){float side=s*.82f,x=cx-side/2,y=cy-side*.6f;c.save();if(!quiet)c.rotate(2*(float)Math.sin(phase*.09f),cx,cy);paint.setShadowLayer(s*.04f,0,s*.025f,0x88000000);paint.setColor(0xfff8f4e9);c.drawRoundRect(x,y,x+side,y+side*1.2f,side*.015f,side*.015f,paint);paint.clearShadowLayer();cover(c,new RectF(x+side*.055f,y+side*.055f,x+side*.945f,y+side*.945f),0);paint.setColor(0xff293b43);paint.setTextAlign(Paint.Align.CENTER);paint.setTypeface(Typeface.create("serif",Typeface.BOLD));paint.setTextSize(side*.065f);c.drawText(fit(name,side*.86f),cx,y+side*1.05f,paint);paint.setTypeface(Typeface.DEFAULT);paint.setTextSize(side*.04f);c.drawText(fit(artist,side*.86f),cx,y+side*1.13f,paint);paint.setTextAlign(Paint.Align.LEFT);c.restore();
  }else if(theme.equals("halo")||theme.equals("vinyl")){float radius=s*(theme.equals("halo")?.33f:.39f);paint.setColor(theme.equals("halo")?accent:0xff252c31);paint.setAlpha(theme.equals("halo")?(int)(40+(quiet?0:12*Math.sin(phase*.07f))+Math.min(70,AudioAnalysis.frame().rmsLeft*200)):255);paint.setShadowLayer(s*.05f,0,0,theme.equals("halo")?accent:0x99000000);c.drawCircle(cx,cy,radius*1.12f,paint);paint.clearShadowLayer();paint.setAlpha(255);if(theme.equals("vinyl")){paint.setColor(0xff566164);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(Math.max(1,s*.004f));for(int k=0;k<6;k++)c.drawCircle(cx,cy,radius*(1.01f+k*.016f),paint);paint.setStyle(Paint.Style.FILL);}c.save();Path clip=new Path();clip.addCircle(cx,cy,radius,Path.Direction.CW);c.clipPath(clip);if(theme.equals("vinyl"))c.rotate(phase,cx,cy);cover(c,new RectF(cx-radius,cy-radius,cx+radius,cy+radius),0);c.restore();if(theme.equals("halo"))spectrum(c,cx,cy,radius*1.17f,s*.13f,true);else{paint.setColor(0xffdce4e1);c.drawCircle(cx,cy,s*.012f,paint);float px=w*.93f,py=h*.10f;c.save();if(!playing)c.rotate(-12,px,py);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(s*.018f);paint.setStrokeCap(Paint.Cap.ROUND);paint.setColor(0xff9eabad);Path arm=new Path();arm.moveTo(px,py);arm.lineTo(px-s*.075f,py+s*.40f);arm.lineTo(px-s*.25f,py+s*.57f);c.drawPath(arm,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0xff303b41);c.drawCircle(px,py,s*.045f,paint);c.restore();}
  }else if(theme.equals("spectrum")){float side=s*.25f;cover(c,new RectF(cx-side/2,h*.025f,cx+side/2,h*.025f+side),side*.12f);if(style==1)spectrum(c,cx,h*.52f,s*.27f,s*.12f,true);else if(style==0)spectrum(c,cx,h*.61f,w*.44f,h*.23f,false);AudioAnalysis.Frame f=AudioAnalysis.frame();wave(c,f.left,w*.06f,h*(style==2?.47f:.78f),w*.88f,h*(style==2?.15f:.055f),accent);if(f.stereo)wave(c,f.right,w*.06f,h*(style==2?.76f:.91f),w*.88f,h*(style==2?.15f:.055f),0xffe6ba94);paint.setTextSize(Math.max(10,s*.034f));paint.setTextAlign(Paint.Align.CENTER);paint.setColor(0xffc7dbe3);c.drawText(f.stereo?"左 / 右声道 · 真实 PCM":AudioAnalysis.status,cx,h*.99f,paint);paint.setTextAlign(Paint.Align.LEFT);
  }else{float side=s*.87f;paint.setColor(0x77040d14);paint.setShadowLayer(s*.04f,0,s*.025f,0x88000000);c.drawRoundRect(cx-side/2,cy-side/2,cx+side/2,cy+side/2,s*.05f,s*.05f,paint);paint.clearShadowLayer();cover(c,new RectF(cx-side/2,cy-side/2,cx+side/2,cy+side/2),s*(theme.equals("minimal")?.025f:.055f));}
  boolean movingArt=theme.equals("cassette")||theme.equals("polaroid")||theme.equals("halo")||theme.equals("vinyl"),movingBackground=frameIntervalMs==0&&(theme.equals("dynamic")||theme.equals("glass"));
  if(playing&&active&&!quiet&&(movingArt||movingBackground)){if(frameIntervalMs>0)postInvalidateDelayed(frameIntervalMs);else postInvalidateOnAnimation();if(movingBackground)getRootView().postInvalidateOnAnimation();}
 }
 private void spectrum(Canvas c,float x,float y,float radius,float height,boolean ring){AudioAnalysis.Frame f=AudioAnalysis.frame();if(f.time==0)return;paint.setColor(accent);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeWidth(Math.max(1,radius*.016f));for(int i=0;i<f.bands.length;i++){float value=Math.max(0,Math.min(1,f.bands[i]*gain));if(value<.001f)continue;if(ring){double a=i*Math.PI*2/f.bands.length-Math.PI/2;float dx=(float)Math.cos(a),dy=(float)Math.sin(a);c.drawLine(x+dx*radius,y+dy*radius,x+dx*(radius+height*value),y+dy*(radius+height*value),paint);}else{float px=x-radius+radius*2*(i+.5f)/f.bands.length;c.drawLine(px,y,px,y-height*value,paint);}}}
 private void wave(Canvas c,float[] values,float x,float y,float w,float h,int color){if(AudioAnalysis.frame().time==0||values.length<2)return;paint.setShader(null);paint.setColor(color);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1.5f);Path p=new Path();for(int i=0;i<values.length;i++){float px=x+w*i/(values.length-1),py=y-values[i]*h;if(i==0)p.moveTo(px,py);else p.lineTo(px,py);}c.drawPath(p,paint);paint.setStyle(Paint.Style.FILL);}
 private void free(){shader=null;paint.setShader(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}}
 void release(){active=false;playing=false;free();}
}
